import React from 'react';
import {
  Box,
  Card,
  CardMedia,
  CardContent,
  Typography,
  Button,
  Stack,
  useTheme
} from '@mui/material';

type Product = {
  id: string;
  name: string;
  image: string;
  price: number;
  description?: string;
};

type Props = {
  products: Product[];
};

const ProductCatalog: React.FC<Props> = () => {
  const theme = useTheme();

  return (
    <Box p={2}>
      <Stack
        direction="row"
        flexWrap="wrap"
        justifyContent="center"
        gap={2}
      >
        {products.map((product) => (
          <Card
            key={product.id}
            sx={{
              width: '100%',
              maxWidth: 280,
              flexGrow: 1,
              display: 'flex',
              flexDirection: 'column',
              backgroundColor: theme.palette.background.default,
              borderRadius: 2,
              boxShadow: 2,
            }}
          >
            <CardMedia
              component="img"
              height="160"
              image={product.image}
              alt={product.name}
              sx={{ objectFit: 'cover' }}
            />
            <CardContent sx={{ flexGrow: 1 }}>
              <Typography variant="h6" fontWeight={600} gutterBottom>
                {product.name}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {product.description}
              </Typography>
              <Typography variant="subtitle1" color="primary" mt={1}>
                ฿{product.price.toLocaleString()}
              </Typography>
            </CardContent>
            <Box p={2}>
              <Button fullWidth variant="contained" color="success">
                สั่งซื้อ
              </Button>
            </Box>
          </Card>
        ))}
      </Stack>
    </Box>
  );
};

export default products;
const sampleProducts = [
  {
    id: '1',
    name: 'ThinkPad X1 Carbon',
    image: '/images/thinkpad.jpg',
    price: 45900,
    description: 'โน้ตบุ๊คสำหรับงานธุรกิจ น้ำหนักเบา ประสิทธิภาพสูง',
  },
  {
    id: '2',
    name: 'Intel Core i7',
    image: '/images/intel.jpg',
    price: 12900,
    description: 'ซีพียูสำหรับงานหนัก เล่นเกม ทำงานกราฟิก',
  },
];
